import sys
import subprocess

def install(package):
    subprocess.check_call([sys.executable, '-m', 'pip', 'install', '--quiet', package])

try:
    import pandas as pd
except ImportError:
    install('pandas')
    import pandas as pd

try:
    import numpy as np
except ImportError:
    install('numpy')
    import numpy as np

try:
    import statsmodels.formula.api as smf
except ImportError:
    install('statsmodels')
    import statsmodels.formula.api as smf

def map_education(x):
    if pd.isna(x):
        return np.nan
    x = str(x).lower().strip()
    if 'doctorate' in x or 'post graduate' in x:
        return 4
    elif 'graduate' in x:
        return 3
    elif '12th' in x or '10th' in x or 'high' in x or 'inter' in x or 'matric' in x or 'ssc' in x or 'hsc' in x:
        return 2
    elif '8th' in x or '5th' in x or 'literate' in x or 'illiterate' in x or 'below' in x or 'primary' in x or 'middle' in x:
        return 1
    else:
        return np.nan

def run_experiment():
    print('Loading dataset...')
    df = pd.read_csv('centre.csv', low_memory=False)

    print('Cleaning and transforming data...')
    df['Education_Ordinal'] = df['MyNeta_education'].apply(map_education)

    valid_const_types = ['GEN', 'SC', 'ST']
    df = df[df['Constituency_Type'].astype(str).str.upper().isin(valid_const_types)].copy()

    df['Reserved'] = np.where(df['Constituency_Type'].astype(str).str.upper() != 'GEN', 1, 0)

    df['Incumbent_Flag'] = df['Incumbent'].astype(str).str.lower().map({
        'true': 1, 'yes': 1, '1': 1, 'false': 0, 'no': 0, '0': 0
    })

    reg_cols = ['Vote_Share_Percentage', 'Education_Ordinal', 'Reserved', 'Party_Type_TCPD', 'Incumbent_Flag', 'Year']
    df_reg = df.dropna(subset=reg_cols).copy()

    print(f'Data ready for regression. Observations: {len(df_reg)}')

    print('Fitting regression model...')
    model = smf.ols('Vote_Share_Percentage ~ Education_Ordinal * Reserved + C(Party_Type_TCPD) + Incumbent_Flag + Year', data=df_reg)
    results = model.fit()

    print('\n--- Regression Results ---')
    print(results.summary().tables[1])

    edu_coef = results.params.get('Education_Ordinal', None)
    interaction_coef = results.params.get('Education_Ordinal:Reserved', None)

    print('\n--- Interpretation ---')
    if edu_coef is not None and interaction_coef is not None:
        print(f'Base effect of Education in General constituencies: {edu_coef:.4f}')
        print(f'Interaction effect (Education x Reserved): {interaction_coef:.4f}')
        print(f'Net effect of Education in Reserved constituencies: {edu_coef + interaction_coef:.4f}')

        pval_interaction = results.pvalues.get('Education_Ordinal:Reserved', 1.0)
        if pval_interaction < 0.05:
            print(f'The interaction term is statistically significant (p = {pval_interaction:.4f}).')
            if interaction_coef < 0:
                print('Conclusion: The electoral premium placed on candidates\' educational qualifications is significantly reduced in Reserved constituencies compared to General constituencies.')
            else:
                print('Conclusion: The electoral premium placed on candidates\' educational qualifications is significantly higher in Reserved constituencies compared to General constituencies.')
        else:
            print(f'The interaction term is not statistically significant (p = {pval_interaction:.4f}).')
            print('Conclusion: There is no significant evidence that constituency reservation alters the electoral premium on education.')
    else:
        print('Could not retrieve required coefficients.')

if __name__ == '__main__':
    run_experiment()
